import test from 'node:test';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';import {savedWorkspaceGuideFixtures,savedRehearsalGuideFixtures,gate} from './helpers/workspace-fixtures.js';
import {prepareWalletSavedSourceBundle,reviewWalletSavedBundle,encodeWalletSavedBundleReview,reviewWalletSavedBundleReceipt,encodeWalletSavedBundleReceiptCheck,walletSavedBundleReceiptCheckText,inspectWalletSavedText} from '../src/file-read-status.js';
const plain=savedRehearsalGuideFixtures()[0].text;
test('V1/V2 saved receipts reproduce every field, including faithful negative bundle conclusions',async()=>{
 const originals=await savedWorkspaceGuideFixtures();for(const text of[plain,originals[0].text]){const bundle=await prepareWalletSavedSourceBundle(text,text),expected=await reviewWalletSavedBundle(bundle.text),saved=encodeWalletSavedBundleReview(expected),checked=await reviewWalletSavedBundleReceipt(expected,saved);assert.equal(checked.matchesRecomputation,true);assert.equal(checked.bundleTextBindingMatches,true);assert.equal(checked.receiptTextDigest,createHash('sha256').update(saved).digest('hex'));assert.equal(checked.expectedSourceFilesAvailable,true);assert.equal((await inspectWalletSavedText(encodeWalletSavedBundleReceiptCheck(checked))).validation,'declared-only');assert.throws(()=>encodeWalletSavedBundleReceiptCheck(JSON.parse(JSON.stringify(checked))));
  const altered=JSON.parse(bundle.text),comparison=JSON.parse(altered.comparisonText);comparison.authenticated=true;altered.comparisonText=JSON.stringify(comparison);const failed=await reviewWalletSavedBundle(JSON.stringify(altered)),negative=await reviewWalletSavedBundleReceipt(failed,encodeWalletSavedBundleReview(failed));assert(negative.matchesRecomputation);assert.equal(negative.expectedBundleComparisonMatches,false);assert.equal(negative.expectedSourceFilesAvailable,false);assert.match(walletSavedBundleReceiptCheckText(negative),/この不一致を解消しません/);
 }
});
test('changed bundle binding, nested comparisons, scope and authority claims are rejected without exposing unknown content',async()=>{
 const expected=await reviewWalletSavedBundle((await prepareWalletSavedSourceBundle(plain,plain)).text),text=encodeWalletSavedBundleReview(expected);
 for(const mutate of[value=>{value.bundleTextDigest='0'.repeat(64);},value=>{value.before.textDigest='0'.repeat(64);},value=>{value.comparison.sourceTextComparison.sameText=false;},value=>{value.comparisonReview.matchesRecomputation=false;},value=>{value.sourceFilesAvailable=false;},value=>{value.authenticated=true;},value=>{delete value.restorable;},value=>{value['PRIVATE_FIELD']='PRIVATE_BODY';}]){const supplied=JSON.parse(text);mutate(supplied);const result=await reviewWalletSavedBundleReceipt(expected,JSON.stringify(supplied));assert.equal(result.matchesRecomputation,false);assert.doesNotMatch(encodeWalletSavedBundleReceiptCheck(result)+walletSavedBundleReceiptCheckText(result),/PRIVATE|0x[0-9a-f]{40}/);}
 const other=await reviewWalletSavedBundle((await prepareWalletSavedSourceBundle(plain,plain+'\n')).text);assert.equal((await reviewWalletSavedBundleReceipt(other,text)).bundleTextBindingMatches,false);
});
test('uploaded review authority, duplicate keys, incompatible schemas, invalid options and oversized receipts are refused',async()=>{
 const expected=await reviewWalletSavedBundle((await prepareWalletSavedSourceBundle(plain,plain)).text),text=encodeWalletSavedBundleReview(expected);await assert.rejects(reviewWalletSavedBundleReceipt(JSON.parse(text),text),{code:'FILE_BUNDLE_RECEIPT_SOURCE'});
 for(const [supplied,code]of[['{"schema":"unknown"}','FILE_BUNDLE_RECEIPT_SCHEMA'],['{"schema":"x","schema":"x"}','FILE_BUNDLE_RECEIPT_JSON'],[' '.repeat(262145),'FILE_BUNDLE_RECEIPT_JSON']])await assert.rejects(reviewWalletSavedBundleReceipt(expected,supplied),{code});let gets=0;await assert.rejects(reviewWalletSavedBundleReceipt(expected,text,{get signal(){gets++;}}),{code:'FILE_BUNDLE_RECEIPT_OPTIONS'});assert.equal(gets,0);await assert.rejects(reviewWalletSavedBundleReceipt(expected,text,{timeoutMs:0}),{code:'FILE_BUNDLE_RECEIPT_OPTIONS'});
});
test('cancelled or timed-out receipt hashing cannot publish an accepted result',async()=>{
 const expected=await reviewWalletSavedBundle((await prepareWalletSavedSourceBundle(plain,plain)).text),text=encodeWalletSavedBundleReview(expected);await assert.rejects(reviewWalletSavedBundleReceipt(expected,text,{signal:AbortSignal.abort()}),{code:'FILE_CANCELLED'});const entered=gate(),blocked=gate(),abort=new AbortController(),work=reviewWalletSavedBundleReceipt(expected,text,{signal:abort.signal,subtle:{digest(){entered.resolve();return blocked.promise;}}});await entered.promise;abort.abort();await assert.rejects(work,{code:'CHECKSUM_CANCELLED'});blocked.resolve(new ArrayBuffer(32));const late=gate();await assert.rejects(reviewWalletSavedBundleReceipt(expected,text,{timeoutMs:15,subtle:{digest:()=>late.promise}}),{code:'CHECKSUM_TIMEOUT'});late.resolve(new ArrayBuffer(32));
});
